import { availableCopies } from "./store.mjs";

const lc = (s) => String(s).toLowerCase();
const byTitle = (a, b) => (lc(a.title) < lc(b.title) ? -1 : lc(a.title) > lc(b.title) ? 1 : 0);

export function search(store, query = {}) {
  const { q, author, tag, yearFrom, yearTo, available, sort = "title", page = 1, pageSize = 10 } = query;
  const words = q ? lc(q).split(/\s+/).filter(Boolean) : [];
  let items = store.books.filter((b) => {
    const hay = lc(b.title) + "\n" + lc(b.author);
    if (!words.every((w) => hay.includes(w))) return false;
    if (author !== undefined && lc(b.author) !== lc(author)) return false;
    if (tag !== undefined && !b.tags.includes(tag)) return false;
    if (yearFrom !== undefined && b.year < yearFrom) return false;
    if (yearTo !== undefined && b.year > yearTo) return false;
    if (available === true && availableCopies(store, b.id) <= 0) return false;
    return true;
  });
  items = items.sort(sort === "year" ? (a, b) => b.year - a.year || byTitle(a, b) : byTitle);
  const total = items.length;
  return { items: items.slice((page - 1) * pageSize, page * pageSize), total, page, pages: Math.ceil(total / pageSize) };
}
