import { daysBetween } from "./dates.mjs";

const GRACE = 2;
const RATE = 0.25;
const CAP = 10;
const cents = (n) => Math.round(n * 100) / 100;
const idNum = (id) => Number(String(id).replace(/\D/g, ""));
const cmpId = (a, b) => idNum(a) - idNum(b) || (a < b ? -1 : a > b ? 1 : 0);

export function finesFor(store, memberId, asOf) {
  const out = [];
  for (const l of store.loans) {
    if (l.memberId !== memberId) continue;
    const daysLate = daysBetween(l.due, l.returned ?? asOf) - GRACE;
    if (daysLate > 0) out.push({ loanId: l.id, bookId: l.bookId, daysLate, amount: cents(Math.min(CAP, daysLate * RATE)) });
  }
  return out.sort((a, b) => cmpId(a.loanId, b.loanId));
}

export function memberBalance(store, memberId, asOf) {
  const fines = finesFor(store, memberId, asOf).reduce((s, f) => s + f.amount, 0);
  const paid = store.payments.filter((p) => p.memberId === memberId).reduce((s, p) => s + p.amount, 0);
  return cents(fines - paid);
}

export function payFine(store, memberId, amount, date) {
  store.payments.push({ memberId, amount, date });
  return memberBalance(store, memberId, date);
}
