import { addBook } from "./store.mjs";

const quote = (v) => (/[",\n]/.test(v) ? `"${v.replace(/"/g, '""')}"` : v);

export function exportBooks(store) {
  const lines = ["id,title,author,year,tags,copies"];
  for (const b of store.books) {
    lines.push([b.id, b.title, b.author, b.year, b.tags.join(";"), b.copies].map((v) => quote(String(v))).join(","));
  }
  return lines.join("\n") + "\n";
}

// Returns [{ line, fields }] where line is the 1-based starting line of each record.
function parse(text) {
  const rows = [];
  let fields = [], field = "", inQ = false, line = 1, start = 1, any = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (inQ) {
      if (c === '"') {
        if (text[i + 1] === '"') { field += '"'; i++; } else inQ = false;
      } else { if (c === "\n") line++; field += c; }
    } else if (c === '"') { inQ = true; any = true; }
    else if (c === ",") { fields.push(field); field = ""; any = true; }
    else if (c === "\n" || c === "\r") {
      if (c === "\r" && text[i + 1] === "\n") i++;
      if (any || field !== "") { fields.push(field); rows.push({ line: start, fields }); }
      fields = []; field = ""; any = false; line++; start = line;
    } else { field += c; any = true; }
  }
  if (any || field !== "") { fields.push(field); rows.push({ line: start, fields }); }
  return rows;
}

const WHOLE = /^-?\d+$/;

export function importBooks(store, text) {
  const rows = parse(text);
  const errors = [];
  let added = 0;
  if (!rows.length) return { added, errors };
  const header = rows[0].fields.map((h) => h.trim());
  const col = (f, name) => {
    const i = header.indexOf(name);
    return i < 0 ? "" : (f[i] ?? "");
  };
  for (const { line, fields } of rows.slice(1)) {
    const title = col(fields, "title").trim();
    const author = col(fields, "author").trim();
    const year = col(fields, "year").trim();
    const copies = col(fields, "copies").trim();
    const tags = col(fields, "tags").trim();
    let message = null;
    if (!title) message = "title is required";
    else if (!author) message = "author is required";
    else if (!WHOLE.test(year)) message = "year must be a whole number";
    else if (copies !== "" && !(/^\d+$/.test(copies) && Number(copies) > 0)) message = "copies must be a positive whole number";
    if (message) { errors.push({ line, message }); continue; }
    addBook(store, {
      title, author, year: Number(year),
      tags: tags ? tags.split(";") : [],
      copies: copies === "" ? 1 : Number(copies),
    });
    added++;
  }
  return { added, errors };
}
