import { addBook } from "./store.mjs";

const field = (v) => {
  const s = String(v);
  return /[",\n]/.test(s) ? `"${s.replaceAll('"', '""')}"` : s;
};

export function exportBooks(store) {
  const lines = ["id,title,author,year,tags,copies"];
  for (const b of store.books) {
    lines.push([b.id, b.title, b.author, b.year, b.tags.join(";"), b.copies].map(field).join(","));
  }
  return lines.join("\n") + "\n";
}

// Splits text into records of { line, fields }, where line is the 1-based start line.
function parseRecords(text) {
  const records = [];
  let fields = [];
  let cur = "";
  let quoted = false;
  let line = 1;
  let start = 1;
  let touched = false;
  const endRecord = () => {
    fields.push(cur);
    if (touched || fields.length > 1) records.push({ line: start, fields });
    fields = [];
    cur = "";
    touched = false;
  };
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (quoted) {
      if (c === '"') {
        if (text[i + 1] === '"') { cur += '"'; i++; } else quoted = false;
      } else {
        if (c === "\n") line++;
        cur += c;
      }
    } else if (c === '"') {
      quoted = true;
      touched = true;
    } else if (c === ",") {
      fields.push(cur);
      cur = "";
      touched = true;
    } else if (c === "\n" || (c === "\r" && text[i + 1] === "\n")) {
      if (c === "\r") i++;
      endRecord();
      line++;
      start = line;
    } else {
      cur += c;
      touched = true;
    }
  }
  if (touched || cur !== "" || fields.length) endRecord();
  return records;
}

export function importBooks(store, text) {
  const records = parseRecords(text);
  const result = { added: 0, errors: [] };
  if (!records.length) return result;
  const cols = records[0].fields.map((h) => h.trim());
  const idx = Object.fromEntries(cols.map((c, i) => [c, i]));
  for (const { line, fields } of records.slice(1)) {
    const get = (name) => (idx[name] === undefined ? "" : (fields[idx[name]] ?? "").trim());
    const title = get("title");
    const author = get("author");
    const yearText = get("year");
    const copiesText = get("copies");
    const err = (message) => result.errors.push({ line, message });
    if (!title) { err("title is required"); continue; }
    if (!author) { err("author is required"); continue; }
    if (!/^-?\d+$/.test(yearText)) { err("year must be a whole number"); continue; }
    if (copiesText !== "" && !/^\d+$/.test(copiesText)) { err("copies must be a positive whole number"); continue; }
    const copies = copiesText === "" ? 1 : Number(copiesText);
    if (copies < 1) { err("copies must be a positive whole number"); continue; }
    const tagsText = get("tags");
    const tags = tagsText === "" ? [] : tagsText.split(";");
    addBook(store, { title, author, year: Number(yearText), tags, copies });
    result.added++;
  }
  return result;
}
