// Read-only reports over a library store.
import { daysBetween } from "./dates.mjs";

const byId = (a, b) => a.localeCompare(b, "en", { numeric: true });

export function overdueReport(store, asOf) {
  return store.loans
    .filter((l) => !l.returned && l.due < asOf)
    .map((l) => {
      const book = store.books.find((b) => b.id === l.bookId);
      const member = store.members.find((m) => m.id === l.memberId);
      return {
        loanId: l.id,
        bookId: l.bookId,
        title: book?.title ?? null,
        memberId: l.memberId,
        memberName: member?.name ?? null,
        daysOverdue: daysBetween(l.due, asOf),
      };
    })
    .sort((a, b) => b.daysOverdue - a.daysOverdue || byId(a.loanId, b.loanId));
}

export function popularBooks(store, { from, to, limit = 5 }) {
  const counts = new Map();
  for (const l of store.loans) {
    if (l.out >= from && l.out <= to) counts.set(l.bookId, (counts.get(l.bookId) ?? 0) + 1);
  }
  return [...counts]
    .map(([bookId, loans]) => ({ bookId, title: store.books.find((b) => b.id === bookId)?.title ?? null, loans }))
    .sort((a, b) => b.loans - a.loans || (a.title ?? "").localeCompare(b.title ?? ""))
    .slice(0, limit);
}

export function memberActivity(store, memberId) {
  const loans = store.loans.filter((l) => l.memberId === memberId);
  return {
    memberId,
    totalLoans: loans.length,
    openLoans: loans.filter((l) => !l.returned).length,
    lastOut: loans.reduce((max, l) => (max === null || l.out > max ? l.out : max), null),
  };
}
