import { createServer as createHttpServer } from "node:http";
import { getBook, checkout } from "./store.mjs";
import { search } from "./search.mjs";
import { memberBalance } from "./fines.mjs";

const NOT_FOUND = { error: "not found" };

function send(res, status, body) {
  res.writeHead(status, { "Content-Type": "application/json" });
  res.end(JSON.stringify(body));
}

function readJson(req) {
  return new Promise((resolve, reject) => {
    let raw = "";
    req.on("data", (c) => (raw += c));
    req.on("end", () => {
      try {
        resolve(raw ? JSON.parse(raw) : {});
      } catch (e) {
        reject(e);
      }
    });
    req.on("error", reject);
  });
}

const num = (v) => (v === null || v === "" || Number.isNaN(Number(v)) ? undefined : Number(v));

async function handle(store, req, res) {
  const url = new URL(req.url, "http://localhost");
  const parts = url.pathname.split("/").filter(Boolean).map(decodeURIComponent);
  const q = url.searchParams;

  if (req.method === "GET" && parts.length === 1 && parts[0] === "books") {
    const opts = {};
    for (const k of ["q", "author", "tag"]) if (q.has(k)) opts[k] = q.get(k);
    for (const k of ["page", "pageSize"]) if (num(q.get(k)) !== undefined) opts[k] = num(q.get(k));
    return send(res, 200, search(store, opts));
  }
  if (req.method === "GET" && parts.length === 2 && parts[0] === "books") {
    const book = getBook(store, parts[1]);
    return book ? send(res, 200, book) : send(res, 404, NOT_FOUND);
  }
  if (req.method === "POST" && parts.length === 1 && parts[0] === "loans") {
    let body;
    try {
      body = await readJson(req);
    } catch {
      return send(res, 400, { error: "invalid json" });
    }
    for (const f of ["bookId", "memberId", "date"]) {
      if (body?.[f] === undefined || body[f] === null || body[f] === "") {
        return send(res, 400, { error: `missing ${f}` });
      }
    }
    try {
      return send(res, 201, checkout(store, body.bookId, body.memberId, body.date));
    } catch (e) {
      return send(res, 409, { error: e.message });
    }
  }
  if (req.method === "GET" && parts.length === 3 && parts[0] === "members" && parts[2] === "balance") {
    const memberId = parts[1];
    return send(res, 200, { memberId, balance: memberBalance(store, memberId, q.get("asOf") ?? undefined) });
  }
  return send(res, 404, NOT_FOUND);
}

export function createServer(store) {
  return createHttpServer((req, res) => {
    handle(store, req, res).catch((e) => send(res, 500, { error: e.message }));
  });
}
