// CSV export/import for books.
import { addBook } from "./store.mjs";

const HEADER = ["id", "title", "author", "year", "tags", "copies"];

const quote = (v) => {
  const s = String(v ?? "");
  return /[",\n\r]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
};

export function exportBooks(store) {
  const lines = [HEADER.join(",")];
  for (const b of store.books) {
    lines.push([b.id, b.title, b.author, b.year, (b.tags ?? []).join(";"), b.copies].map(quote).join(","));
  }
  return lines.join("\n") + "\n";
}

// Returns [{ line, fields }] where line is the 1-based line the record starts on.
function parse(text) {
  const records = [];
  let fields = [], field = "", inQuotes = false, line = 1, start = 1, any = false;
  const endRecord = () => {
    fields.push(field);
    records.push({ line: start, fields });
    fields = []; field = ""; any = false;
  };
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (inQuotes) {
      if (c === '"') {
        if (text[i + 1] === '"') { field += '"'; i++; } else inQuotes = false;
      } else {
        if (c === "\n") line++;
        field += c;
      }
    } else if (c === '"') { inQuotes = true; any = true; }
    else if (c === ",") { fields.push(field); field = ""; any = true; }
    else if (c === "\n" || c === "\r") {
      if (c === "\r" && text[i + 1] === "\n") i++;
      if (any || field !== "" || fields.length) endRecord();
      line++;
      start = line;
    } else { field += c; any = true; }
  }
  if (any || field !== "" || fields.length) endRecord();
  return records;
}

export function importBooks(store, text) {
  const added = [];
  const errors = [];
  const [head, ...rows] = parse(text);
  if (!head) return { added, errors };
  const cols = head.fields.map((h) => h.trim());
  const idx = (n) => cols.indexOf(n);
  for (const { line, fields } of rows) {
    const get = (n) => (idx(n) < 0 ? "" : (fields[idx(n)] ?? "").trim());
    const title = get("title"), author = get("author");
    const yearS = get("year"), copiesS = get("copies");
    const err = (message) => errors.push({ line, message });
    if (!title) { err("title is required"); continue; }
    if (!author) { err("author is required"); continue; }
    if (!/^-?\d+$/.test(yearS)) { err("year must be a whole number"); continue; }
    if (copiesS !== "" && !/^\d+$/.test(copiesS)) { err("copies must be a positive whole number"); continue; }
    const copies = copiesS === "" ? 1 : Number(copiesS);
    if (copies < 1) { err("copies must be a positive whole number"); continue; }
    const tagsS = get("tags");
    const tags = tagsS === "" ? [] : tagsS.split(";").map((t) => t.trim()).filter(Boolean);
    added.push(addBook(store, { title, author, year: Number(yearS), tags, copies }));
  }
  return { added, errors };
}
